package week_02;

import java.awt.*;import javax.swing.*;
public class frm_AES_CTR extends JFrame {
 private final JTextField key=new JTextField(36),nonce=new JTextField(36);private final JTextArea plain=new JTextArea(4,56),cipher=new JTextArea(4,56);private final JLabel status=new JLabel("Sẵn sàng.");
 public frm_AES_CTR(){super("AES-CTR Cipher");setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel();p.setBorder(BorderFactory.createEmptyBorder(18,20,18,20));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel("BÀI NÂNG CAO 01 - AES-256 CHẾ ĐỘ CTR");h.setFont(new Font("Segoe UI",Font.BOLD,18));p.add(h);p.add(new JLabel("Plaintext:"));p.add(area(plain));JButton gk=new JButton("Generate Key"),gn=new JButton("Generate Nonce");gk.addActionListener(e->{key.setText(AESCTRCipher.newKey());status.setText("Đã tạo khóa ngẫu nhiên 256 bit.");});gn.addActionListener(e->{nonce.setText(AESCTRCipher.newNonce());status.setText("Đã tạo nonce 96 bit.");});p.add(row("Key (Base64):",key,gk));p.add(row("Nonce (Base64):",nonce,gn));p.add(new JLabel("Ciphertext:"));p.add(area(cipher));JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton en=new JButton("Encrypt"),de=new JButton("Decrypt"),sv=new JButton("Save File"),op=new JButton("Open File");en.addActionListener(e->crypt(true));de.addActionListener(e->crypt(false));sv.addActionListener(e->save());op.addActionListener(e->open());b.add(en);b.add(de);b.add(sv);b.add(op);p.add(b);p.add(status);setContentPane(p);pack();setLocationRelativeTo(null);}
 private JPanel row(String label,JTextField field,JButton button){JPanel r=new JPanel(new FlowLayout(FlowLayout.LEFT));r.add(new JLabel(label));r.add(field);r.add(button);return r;}private JScrollPane area(JTextArea a){a.setLineWrap(true);a.setWrapStyleWord(true);return new JScrollPane(a);}
 private void crypt(boolean enc){try{if(enc){cipher.setText(AESCTRCipher.encrypt(plain.getText(),key.getText(),nonce.getText()));status.setText("Đã mã hóa AES-CTR. "+HistoryDao.tryInsert("AES-CTR","ENCRYPT",null,plain.getText().length(),cipher.getText().length()));}else{plain.setText(AESCTRCipher.decrypt(cipher.getText(),key.getText(),nonce.getText()));status.setText("Đã giải mã AES-CTR. "+HistoryDao.tryInsert("AES-CTR","DECRYPT",null,cipher.getText().length(),plain.getText().length()));}}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}}
 private void save(){String f=FileTextIO.save(this,AESCTRCipher.toFile(nonce.getText(),cipher.getText()),"aes_ctr_ciphertext.txt");if(f!=null)status.setText("Đã lưu nonce và bản mã.");}private void open(){String s=FileTextIO.open(this);if(s==null)return;try{String[] a=AESCTRCipher.fromFile(s);nonce.setText(a[0]);cipher.setText(a[1]);status.setText("Đã khôi phục nonce và bản mã; nhập đúng key rồi giải mã.");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}
}
